// ──────────────────────────── tests ──────────────────────────────────────

test('sendJson writes the status, the body and a JSON content-type', async () => {
  await withServer(
    (req, res) => sendJson(res, 201, { id: 1, text: 'buy milk' }),
    async (request) => {
      const res = await request('/');
      eq(res.status, 201);
      eq(res.json(), { id: 1, text: 'buy milk' });
      ok(res.headers.get('content-type').includes('application/json'));
    }
  );
});

test('sendJson can answer with an error status too', async () => {
  await withServer(
    (req, res) => sendJson(res, 404, { error: 'not found' }),
    async (request) => {
      const res = await request('/nope');
      eq(res.status, 404);
      eq(res.json(), { error: 'not found' });
    }
  );
});

test('content-length counts bytes, not characters', async () => {
  const data = { note: 'café ☕' };
  await withServer(
    (req, res) => sendJson(res, 200, data),
    async (request) => {
      const res = await request('/');
      const expected = Buffer.byteLength(JSON.stringify(data), 'utf8');
      eq(res.headers.get('content-length'), String(expected));
      eq(res.json(), data);
    }
  );
});

test('redirect defaults to 302 and sets Location', async () => {
  await withServer(
    (req, res) => redirect(res, '/target'),
    async (request) => {
      const res = await request('/old', { redirect: 'manual' });
      eq(res.status, 302);
      eq(res.headers.get('location'), '/target');
    }
  );
});

test('redirect takes an explicit status for permanent moves', async () => {
  await withServer(
    (req, res) => redirect(res, 'https://example.test/new', 301),
    async (request) => {
      const res = await request('/old', { redirect: 'manual' });
      eq(res.status, 301);
      eq(res.headers.get('location'), 'https://example.test/new');
    }
  );
});

test('noContent answers 204 with an empty body and no content-type', async () => {
  await withServer(
    (req, res) => noContent(res),
    async (request) => {
      const res = await request('/', { method: 'DELETE' });
      eq(res.status, 204);
      eq(res.body, '');
      eq(res.headers.get('content-type'), null);
    }
  );
});

// ──────────────────────────── tests ──────────────────────────────────────

test('parseQuery turns a search string into an object', () => {
  eq(parseQuery('?q=cats&page=2'), { q: 'cats', page: '2' });
  eq(parseQuery('q=cats'), { q: 'cats' });
  eq(parseQuery(''), {});
});

test('a repeated key becomes an array, a single key stays a string', () => {
  eq(parseQuery('?tag=js&tag=node'), { tag: ['js', 'node'] });
  eq(parseQuery('?tag=js'), { tag: 'js' });
});

test('query values are decoded, and a bare key is an empty string', () => {
  eq(parseQuery('?q=hello%20there'), { q: 'hello there' });
  eq(parseQuery('?q=hello+there'), { q: 'hello there' });
  eq(parseQuery('?debug'), { debug: '' });
});

test('the context splits the path from the query string', () => {
  const ctx = makeContext({ method: 'GET', url: '/search?q=cats', headers: {} });
  eq(ctx.path, '/search');
  eq(ctx.query, { q: 'cats' });
});

test('the method is upper-cased', () => {
  eq(makeContext({ method: 'post', url: '/notes', headers: {} }).method, 'POST');
});

test('a trailing slash is normalised away, but "/" survives', () => {
  const at = (url) => makeContext({ method: 'GET', url, headers: {} }).path;
  eq(at('/notes/'), '/notes');
  eq(at('/notes'), '/notes');
  eq(at('/'), '/');
  eq(at('/?q=1'), '/');
});

test('header lookup ignores case', () => {
  const ctx = makeContext({
    method: 'GET',
    url: '/',
    headers: { 'content-type': 'application/json' },
  });
  eq(ctx.header('Content-Type'), 'application/json');
  eq(ctx.header('content-type'), 'application/json');
  eq(ctx.header('x-missing'), undefined);
});

test('it works on a real request off the wire', async () => {
  await withServer(
    (req, res) => {
      const ctx = makeContext(req);
      res.writeHead(200, { 'content-type': 'application/json' });
      res.end(JSON.stringify({
        method: ctx.method,
        path: ctx.path,
        query: ctx.query,
        accept: ctx.header('Accept'),
      }));
    },
    async (request) => {
      const res = await request('/notes/?tag=a&tag=b', {
        headers: { accept: 'application/json' },
      });
      const seen = res.json();
      eq(seen.method, 'GET');
      eq(seen.path, '/notes');
      eq(seen.query, { tag: ['a', 'b'] });
      ok(seen.accept.includes('application/json'));
    }
  );
});

// ──────────────────────────── tests ──────────────────────────────────────

const routes = [
  {
    method: 'GET',
    path: '/health',
    handler: (req, res) => sendJson(res, 200, { status: 'ok' }),
  },
  {
    method: 'GET',
    path: '/notes',
    handler: (req, res) => sendJson(res, 200, { notes: [] }),
  },
  {
    method: 'POST',
    path: '/notes',
    handler: (req, res) => sendJson(res, 201, { created: true }),
  },
  {
    method: 'DELETE',
    path: '/notes',
    handler: (req, res) => sendJson(res, 200, { cleared: true }),
  },
];

test('a registered method and path reach their handler', async () => {
  await withServer(createRouteHandler(routes), async (request) => {
    const res = await request('/health');
    eq(res.status, 200);
    eq(res.json(), { status: 'ok' });
  });
});

test('the same path with a different method gets its own handler', async () => {
  await withServer(createRouteHandler(routes), async (request) => {
    eq((await request('/notes')).json(), { notes: [] });
    const created = await request('/notes', { method: 'POST' });
    eq(created.status, 201);
    eq(created.json(), { created: true });
  });
});

test('an unknown path is a 404', async () => {
  await withServer(createRouteHandler(routes), async (request) => {
    const res = await request('/nope');
    eq(res.status, 404);
    eq(res.json(), { error: 'not found' });
  });
});

test('a known path with an unregistered method is a 405, not a 404', async () => {
  await withServer(createRouteHandler(routes), async (request) => {
    const res = await request('/notes', { method: 'PUT' });
    eq(res.status, 405);
    eq(res.json(), { error: 'method not allowed' });
  });
});

test('a 405 lists every method that path does support', async () => {
  await withServer(createRouteHandler(routes), async (request) => {
    const res = await request('/notes', { method: 'PUT' });
    eq(res.headers.get('allow'), 'DELETE, GET, POST');
  });
});

test('the Allow header only covers the path that was asked for', async () => {
  await withServer(createRouteHandler(routes), async (request) => {
    const res = await request('/health', { method: 'POST' });
    eq(res.status, 405);
    eq(res.headers.get('allow'), 'GET');
  });
});

test('a query string does not break the match', async () => {
  await withServer(createRouteHandler(routes), async (request) => {
    const res = await request('/health?cacheBust=1');
    eq(res.status, 200);
    eq(res.json(), { status: 'ok' });
  });
});

test('a trailing slash matches the route as registered', async () => {
  await withServer(createRouteHandler(routes), async (request) => {
    eq((await request('/notes/')).status, 200);
    ok((await request('/notes/', { method: 'PUT' })).status === 405);
  });
});

// ──────────────────────────── tests ──────────────────────────────────────

const routes = [
  {
    method: 'GET',
    path: '/users/:id',
    handler: (req, res) => sendJson(res, 200, { user: req.params.id }),
  },
  {
    method: 'GET',
    path: '/users/:userId/posts/:postId',
    handler: (req, res) => sendJson(res, 200, req.params),
  },
  {
    method: 'GET',
    path: '/health',
    handler: (req, res) => sendJson(res, 200, { status: 'ok' }),
  },
];

test('an exact static match captures no params', () => {
  eq(matchPath('/health', '/health'), {});
  eq(matchPath('/', '/'), {});
});

test('a pattern that does not line up returns null', () => {
  eq(matchPath('/health', '/healthz'), null);
  eq(matchPath('/users/:id', '/users'), null);
  eq(matchPath('/users', '/users/42'), null);
});

test('a :segment captures its value by name', () => {
  eq(matchPath('/users/:id', '/users/42'), { id: '42' });
  eq(typeof matchPath('/users/:id', '/users/42').id, 'string');
});

test('several params in one pattern all come back', () => {
  eq(matchPath('/users/:userId/posts/:postId', '/users/7/posts/99'), {
    userId: '7',
    postId: '99',
  });
});

test('a param never swallows a slash', () => {
  eq(matchPath('/files/:name', '/files/notes.txt'), { name: 'notes.txt' });
  eq(matchPath('/files/:name', '/files/deep/notes.txt'), null);
});

test('param values are percent-decoded', () => {
  eq(matchPath('/tags/:tag', '/tags/data%20science'), { tag: 'data science' });
});

test('the handler sees req.params on a real request', async () => {
  await withServer(createRouteHandler(routes), async (request) => {
    const one = await request('/users/42');
    eq(one.status, 200);
    eq(one.json(), { user: '42' });

    const nested = await request('/users/7/posts/99');
    eq(nested.json(), { userId: '7', postId: '99' });
  });
});

test('a path no route claims is a 404', async () => {
  await withServer(createRouteHandler(routes), async (request) => {
    const res = await request('/users/7/settings');
    eq(res.status, 404);
    eq(res.json(), { error: 'not found' });
    ok((await request('/health')).status === 200);
  });
});

// ──────────────────────────── tests ──────────────────────────────────────

test('middleware run in the order they were registered', async () => {
  const seen = [];
  const app = createApp();
  app.use((req, res, next) => {
    seen.push('first');
    next();
  });
  app.use((req, res, next) => {
    seen.push('second');
    next();
  });
  app.use((req, res) => sendJson(res, 200, { seen }));

  await withServer(app.handler, async (request) => {
    eq((await request('/')).json(), { seen: ['first', 'second'] });
  });
});

test('use() returns the app, so registrations chain', () => {
  const app = createApp();
  eq(app.use(() => {}), app);
});

test('a middleware that never calls next ends the chain', async () => {
  const later = spy();
  const app = createApp();
  app.use((req, res) => sendJson(res, 200, { from: 'first' }));
  app.use((req, res, next) => {
    later();
    next();
  });

  await withServer(app.handler, async (request) => {
    eq((await request('/')).json(), { from: 'first' });
    eq(later.callCount, 0);
  });
});

test('middleware can decorate the request for the ones after it', async () => {
  const app = createApp();
  app.use((req, res, next) => {
    req.user = { name: 'ada' };
    next();
  });
  app.use((req, res) => sendJson(res, 200, { user: req.user.name }));

  await withServer(app.handler, async (request) => {
    eq((await request('/')).json(), { user: 'ada' });
  });
});

test('reaching the end of the chain is a 404', async () => {
  const app = createApp();
  app.use((req, res, next) => next());
  app.use((req, res, next) => next());

  await withServer(app.handler, async (request) => {
    const res = await request('/anything');
    eq(res.status, 404);
    eq(res.json(), { error: 'not found' });
  });
});

test('an app with no middleware at all still answers', async () => {
  await withServer(createApp().handler, async (request) => {
    eq((await request('/')).status, 404);
  });
});

test('calling next() twice does not run the rest of the chain twice', async () => {
  const counted = spy();
  const app = createApp();
  app.use((req, res, next) => {
    next();
    next();
  });
  app.use((req, res) => {
    counted();
    if (!res.writableEnded) sendJson(res, 200, { ok: true });
  });

  await withServer(app.handler, async (request) => {
    eq((await request('/')).json(), { ok: true });
    eq(counted.callCount, 1);
  });
});

test('a middleware that already responded cannot re-open the chain', async () => {
  const later = spy();
  const app = createApp();
  app.use((req, res, next) => {
    sendJson(res, 202, { from: 'first' });
    next();
  });
  app.use((req, res, next) => {
    later();
    next();
  });

  await withServer(app.handler, async (request) => {
    const res = await request('/');
    eq(res.status, 202);
    eq(later.callCount, 0);
  });
});

