});

test('the highest q wins, not the first one listed', () => {
  eq(chooseType('application/json;q=0.2, text/html;q=0.9', OFFERED), 'text/html');
  eq(chooseType('text/html;q=0.1, application/json', OFFERED), 'application/json');
