test('wildcards match: */* takes the default, text/* takes a text type', () => {
  eq(chooseType('*/*', OFFERED), 'application/json');
  eq(chooseType('text/*', OFFERED), 'text/plain');
  eq(chooseType('text/html, */*;q=0.1', OFFERED), 'text/html');
