const byApiKey = (req) => req.headers['x-api-key'] ?? 'anonymous';

function appWith(limiter, reached = () => {}) {
  const app = createApp();
  app.use(limiter);
  app.use((req, res) => {
    reached();
    sendJson(res, 200, { ok: true });
  });
  return app;
}

