  const log = spy();
  await withApp(notesApp(log), async (request) => {
    await request('/notes');
    await request('/nope');
    eq(log.callCount, 2);
    eq(log.calls[0][0], 'GET /notes');
    eq(log.calls[1][0], 'GET /nope');
  });
});

