  await withApp(notesApp(), async (request) => {
    await request('/notes', asJson({ text: 'buy milk' }));
    eq((await request('/notes/1')).json(), { id: 1, text: 'buy milk' });

    const missing = await request('/notes/99');
    eq(missing.status, 404);
